function sortComponentsByAlphabet(items) {
  return [...items].sort((a, b) => {
    const getEnglishName = (text) => text.split(" ")[0];
    return getEnglishName(a.text).localeCompare(getEnglishName(b.text));
  });
}
function componentToSidebarItem(component) {
  return {
    text: component.text,
    link: component.link
  };
}

// .vitepress/config/Sidebar/getComponents.ts
var getComponentsSidebar = (filterStatus) => {
  let filteredComponents = componentsMetadata;
  if (filterStatus && filterStatus.length > 0) {
    filteredComponents = componentsMetadata.filter(
      (component) => !component.status || filterStatus.includes(component.status)
    );
  }
  const componentsByCategory = {};
  filteredComponents.forEach((component) => {
    const category = component.category;
    if (!componentsByCategory[category]) {
      componentsByCategory[category] = [];
    }
    componentsByCategory[category].push(component);
  });
  Object.keys(componentsByCategory).forEach((category) => {
    componentsByCategory[category] = sortComponentsByAlphabet(
      componentsByCategory[category]
    );
  });
  const sidebarItems = [];
  categoryOrder.forEach((category) => {
    if (componentsByCategory[category] && componentsByCategory[category].length > 0) {
      sidebarItems.push({
        text: categoryLabels[category],
        collapsed: false,
        items: componentsByCategory[category].map(componentToSidebarItem)
      });
    }
  });
  return sidebarItems;
};

